<template><section><el-alert v-if="error" type="error" :title="error" :closable="false" /><p>资料处置依次经过制度版本复核、到期预检、另一管理员审批和原申请人执行。未到期、未终结或仍有业务引用的记录会被阻止；审计和删除墓碑永久保留供恢复时重放。</p><el-button @click="load">刷新处置状态</el-button><el-form label-position="top" class="retention-grid"><el-form-item label="记录类型"><el-select v-model="policy.kind"><el-option v-for="(label,value) in kinds" :key="value" :value="value" :label="label" /></el-select></el-form-item><el-form-item label="保留天数（正式业务从归档日起）"><el-input-number v-model="policy.days" :min="1" :max="36500" /></el-form-item><el-form-item label="生效时间"><el-input v-model="policy.effectiveAt" type="datetime-local" /></el-form-item><el-form-item label="批准制度依据"><el-input v-model="policy.basis" placeholder="学校已批准的制度名称及编号" /></el-form-item><el-form-item label="变更原因"><el-input v-model="policy.reason" /></el-form-item><el-form-item><el-button type="primary" :loading="busy" @click="createPolicy">申请新留存策略版本</el-button></el-form-item></el-form><article v-for="p in state.policies" :key="p.id" class="retention-card"><strong>{{kinds[p.kind]}} · 保留{{p.days}}天 · v{{p.version}} · {{p.status}}</strong><p>依据：{{p.basis}}；{{p.reason}}</p><template v-if="p.status==='pending'&&p.authorId!==user.id"><el-button @click="decide('policies',p,true)">复核策略</el-button><el-button @click="decide('policies',p,false)">驳回</el-button></template><el-button v-if="p.status==='approved'" @click="preview(p)">生成到期处置预检</el-button></article><h3>到期处置清单</h3><article v-for="r in state.reviews" :key="r.id" class="retention-card"><strong>{{r.status}} · 可处置{{r.items.length}}条 · 阻止{{r.blocked.length}}条</strong><p>申请编号 {{r.id}} · {{r.reason}}</p><el-collapse><el-collapse-item title="查看元数据预检结果"><el-table :data="[...r.items,...r.blocked]" max-height="280"><el-table-column prop="kind" label="类别" /><el-table-column prop="recordId" label="记录编号" min-width="250" /><el-table-column prop="reason" label="阻止原因（空为符合条件）" min-width="220" /></el-table></el-collapse-item></el-collapse><template v-if="r.status==='pending'&&r.requesterId!==user.id"><el-button @click="decide('reviews',r,true)">批准此处置清单</el-button><el-button @click="decide('reviews',r,false)">驳回</el-button></template><el-button v-if="r.status==='approved'&&r.requesterId===user.id" type="danger" :loading="busy" @click="execute(r)">执行已获双审的到期删除</el-button></article><h3>删除墓碑与附件清除状态</h3><el-table :data="state.tombstones"><el-table-column prop="recordKind" label="类别" /><el-table-column prop="recordId" label="记录编号" min-width="250" /><el-table-column prop="deletedAt" label="删除时间" min-width="200" /><el-table-column label="附件清除"><template #default="{row}">{{row.filesPurged?'已完成':row.purgeError||'等待清除核验'}}</template></el-table-column></el-table></section></template>
<script setup lang="ts">
import {onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api}from'@/api';defineProps<{user:Record<string,any>}>();const kinds:Record<string,string>={file:'无业务引用的附件',collection_export:'材料导出缓存',student_import:'学生导入预检',college_import:'任务与床位导入预检',account_import:'账号导入预检',operation:'幂等响应缓存',account_invite:'一次性邀请',request:'已终结学生事项',worklog:'已归档工作记录',collection:'已归档材料采集及答卷'};const state=ref<any>({policies:[],reviews:[],tombstones:[]}),busy=ref(false),error=ref(''),policy=reactive({kind:'collection_export',days:7,effectiveAt:'',basis:'',reason:''});async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();state.value=await api('/retention')}catch(e:any){error.value=e.message;ElMessage.error(e.message)}finally{busy.value=false}}async function load(){await run(async()=>{})}async function createPolicy(){await run(async()=>{await api('/retention/policies',{method:'POST',body:policy});ElMessage.success('等待另一名管理员复核')})}async function decide(type:string,record:any,approved:boolean){try{const{value}=await ElMessageBox.prompt('填写复核依据或驳回原因','到期处置复核');await run(async()=>{await api(`/retention/${type}/${record.id}/approve`,{method:'POST',body:{approved,reason:value}})})}catch{}}async function preview(p:any){try{const{value}=await ElMessageBox.prompt('填写本次资料处置原因','到期预检');await run(async()=>{await api('/retention/preview',{method:'POST',body:{policyId:p.id,reason:value}})})}catch{}}async function execute(r:any){try{await ElMessageBox.confirm(`将永久清除已获批且仍符合条件的 ${r.items.length} 条到期记录，保留审计及删除墓碑。`,'执行已批准删除',{type:'warning',confirmButtonText:'执行删除'});await run(async()=>{await api(`/retention/reviews/${r.id}/execute`,{method:'POST'});ElMessage.success('数据库处置完成，附件清除由后台核验')})}catch{}}onMounted(load);
</script>
<style scoped>.retention-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:18px}.retention-card{border:1px solid #dbe3ed;padding:16px;border-radius:10px;margin:14px 0}p{color:var(--muted,#64748b);line-height:1.8}@media(max-width:700px){.retention-grid{grid-template-columns:1fr}}</style>
